package com.studiocliquim.arquivos;
import android.app.*;import android.os.*;import android.content.*;import java.io.*;import java.nio.file.*;import java.util.*;
public class SmokeTest extends Instrumentation {
 int checks=0;void ok(boolean b,String msg)throws Exception{if(!b)throw new Exception(msg);checks++;}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();try{Context c=getTargetContext();FileEngine e=new FileEngine(c);File dir=new File(Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOWNLOADS),"Cliquim-QA-"+System.currentTimeMillis());ok(dir.mkdir(),"fixture mkdir");FileEngine.Node root=e.local(dir);FileEngine.Node a=e.createDirectory(root,"Origem"),b=e.createDirectory(root,"Destino");File src=new File(a.file,"Teste.txt");Files.write(src.toPath(),"Olá Cliquim\nconteúdo de teste".getBytes(java.nio.charset.StandardCharsets.UTF_8));FileEngine.Node n=e.local(src);ok(e.list(a).size()==1,"list");FileEngine.Node copy=e.copy(n,b,false);ok(src.exists(),"source preserved");ok(Arrays.equals(Files.readAllBytes(src.toPath()),Files.readAllBytes(copy.file.toPath())),"copy bytes");FileEngine.Node conflict=e.copy(n,b,false);ok(!copy.id.equals(conflict.id),"conflict unique");ok(e.list(b).size()==2,"no overwrite");FileEngine.Node renamed=e.rename(conflict,"Renomeado.txt");ok(renamed.name.equals("Renomeado.txt"),"rename");boolean refused=false;try{e.rename(renamed,copy.name);}catch(IOException x){refused=true;}ok(refused,"rename conflict refused");ok(renamed.file.exists(),"rename source kept");FileEngine.Node moved=e.copy(n,b,true);ok(!src.exists(),"move removed verified source");ok(moved.file.exists(),"move destination exists");File sub=new File(a.file,"Filha");ok(sub.mkdir(),"child fixture");refused=false;try{e.copy(a,e.local(sub),false);}catch(IOException x){refused=true;}ok(refused,"descendant refused");FileEngine.Node folderCopy=e.copy(a,b,false);ok(folderCopy.directory&&new File(folderCopy.file,"Filha").exists(),"folder recursive copy");e.cancelled.set(true);refused=false;try{e.copy(copy,a,false);}catch(IOException x){refused=true;}ok(refused,"cancel refused");e.resetCancellation();ok(copy.file.exists(),"cancel preserved source");e.delete(renamed);ok(!renamed.file.exists(),"delete fixture");refused=false;try{e.local(new File(c.getFilesDir(),"secret"));}catch(IOException x){refused=true;}ok(refused,"private path blocked");refused=false;try{FileEngine.validName("../bad");}catch(IOException x){refused=true;}ok(refused,"traversal blocked");Intent i=new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);Activity activity=startActivitySync(i);ok(activity!=null,"activity launch");runOnMainSync(()->{MainActivity m=(MainActivity)activity;m.openLocal();});waitForIdleSync();Thread.sleep(800);runOnMainSync(()->{MainActivity m=(MainActivity)activity;m.viewMenu();});waitForIdleSync();checks++;result.putString("stream","PASS "+checks+" checks; fixture "+dir.getName());finish(Activity.RESULT_OK,result);}catch(Throwable x){result.putString("stream","FAIL at "+checks+": "+x);finish(Activity.RESULT_CANCELED,result);}}
}
